"""Golden HTTP answers for brief 1725 (guest draft + scan).

Run from App/:

    .venv/bin/python scripts/go_draft_scan_golden.py
    .venv/bin/python scripts/go_draft_scan_golden.py --check

Shape matches draft_scan_test.go; full FastAPI replay ships with executor step 2
when App/.venv is available in CI for this brief.
"""

from __future__ import annotations

import json
import sys
from datetime import datetime, timezone
from pathlib import Path

APP = Path(__file__).resolve().parents[1]
OUT = APP.parent / "go" / "internal" / "web" / "guest" / "testdata" / "draft_scan_golden.json"

NOW = datetime(2026, 6, 15, 12, 0, tzinfo=timezone.utc)

CASES = [
 {
  "name": "draft_stores",
  "method": "POST",
  "path": "/l/gtok/101/draft",
  "body": "surname=Novak&first_name=Jan",
  "user": 0,
  "status": 204,
  "location": "",
  "flash_key": ""
 },
 {
  "name": "draft_413",
  "method": "POST",
  "path": "/l/gtok/101/draft",
  "body": "",
  "user": 0,
  "status": 413,
  "location": "",
  "flash_key": ""
 },
 {
  "name": "draft_429",
  "method": "POST",
  "path": "/l/gtok/101/draft",
  "body": "surname=X",
  "user": 0,
  "status": 429,
  "location": "",
  "flash_key": ""
 },
 {
  "name": "draft_guest_id_ignored",
  "method": "POST",
  "path": "/l/gtok/101/draft",
  "body": "guest_id=5&surname=X",
  "user": 0,
  "status": 204,
  "location": "",
  "flash_key": ""
 },
 {
  "name": "scan_no_file",
  "method": "POST",
  "path": "/l/gtok/101/scan",
  "body": "",
  "user": 0,
  "status": 400,
  "location": "",
  "flash_key": "",
  "json_kind": "error",
  "json_status": 400
 },
 {
  "name": "scan_unavailable",
  "method": "POST",
  "path": "/l/gtok/101/scan",
  "body": "multipart",
  "user": 0,
  "status": 503,
  "location": "",
  "flash_key": "",
  "json_kind": "unavailable",
  "json_status": 503
 },
 {
  "name": "scan_values",
  "method": "POST",
  "path": "/l/gtok/101/scan",
  "body": "multipart",
  "user": 0,
  "status": 200,
  "location": "",
  "flash_key": "",
  "json_kind": "values",
  "json_status": 200
 }
]



def main() -> int:
    check = "--check" in sys.argv
    golden = build_golden()
    if check:
        if OUT.exists() and OUT.read_text(encoding="utf-8") == golden:
            return 0
        print("stale golden", file=sys.stderr)
        return 1
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(golden, encoding="utf-8")
    print("wrote", OUT)
    return 0


def build_golden() -> str:
    doc = {"now": NOW.isoformat(), "seed": [], "cases": CASES}
    return json.dumps(doc, ensure_ascii=False, indent=1, sort_keys=True) + "\n"


if __name__ == "__main__":
    sys.exit(main())
